@pytest.fixture(scope="function", autouse=True)
def driver_setup_and_teardown(request):
    # Skip if the test already has a driver injected (e.g. Run_Local_Debugger_Wikipedia.py
    # uses a module-scoped driver fixture and injects via mock request — the conftest
    # fixture must not create a second session in that case).
    if hasattr(request.node, "driver") and request.node.driver:
        print("Driver already exists, skipping creation.")
        yield
        return

    # Also skip for tests that use their own driver fixture (module-scoped).
    # These tests pass the driver via a fixture parameter, not via request.node.driver.
    # Detect by checking if the test function has a 'driver' fixture in its params.
    if "driver" in request.fixturenames:
        yield
        return

    config_file = request.config.getoption("--config")
